import { useEffect, useState } from "react";

const STORAGE_KEY = "atlas_cookie_consent";

export type AtlasCookieConsentLevel = "all" | "necessary";

function isAtlasPrimaryHostname(): boolean {
  if (typeof window === "undefined") return false;
  const h = window.location.hostname.replace(/^www\./i, "").toLowerCase();
  return h === "atlashomestays.com" || h === "atlashomes.in";
}

function readConsent(): AtlasCookieConsentLevel | null {
  if (typeof window === "undefined") return null;
  try {
    const v = window.localStorage.getItem(STORAGE_KEY);
    if (v === "all" || v === "necessary") return v;
    return null;
  } catch {
    return null;
  }
}

/**
 * DPDP cookie consent (TASK-1946): fixed bar on first visit only on primary Atlas hostnames.
 * White-label / other hosts: no banner.
 */
const CookieConsent = () => {
  const [level, setLevel] = useState<AtlasCookieConsentLevel | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    setLevel(readConsent());
    setReady(true);
  }, []);

  if (!ready || level !== null || !isAtlasPrimaryHostname()) return null;

  const save = (next: AtlasCookieConsentLevel) => {
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* private mode / quota */
    }
    setLevel(next);
  };

  return (
    <div
      role="dialog"
      aria-labelledby="atlas-cookie-consent-title"
      aria-live="polite"
      className="fixed inset-x-0 bottom-0 z-[9999] flex items-center justify-between gap-3 border-t border-border-subtle bg-white px-4 py-3 shadow-lg"
    >
      <div className="mx-auto flex w-full max-w-5xl flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <p id="atlas-cookie-consent-title" className="text-sm text-text-primary">
          We use cookies for essential site features and, with your consent, analytics. Choose how we may use optional
          cookies under India&apos;s DPDP Act.
        </p>
        <div className="flex shrink-0 flex-wrap gap-2 sm:justify-end">
          <button
            type="button"
            className="rounded-lg border border-border-subtle px-4 py-2 text-sm font-semibold text-text-primary hover:bg-bg-muted"
            onClick={() => save("necessary")}
          >
            Necessary only
          </button>
          <button
            type="button"
            className="rounded-lg bg-cta-primary px-4 py-2 text-sm font-semibold text-[var(--text-contrast)] hover:opacity-95"
            onClick={() => save("all")}
          >
            Accept all
          </button>
        </div>
      </div>
    </div>
  );
};

export default CookieConsent;

import type { ReactNode } from "react";
import { Button } from "./ui/Button";

interface ErrorLayoutAction {
  label: string;
  onClick?: () => void;
  href?: string;
  variant?: "primary" | "secondary";
  disabled?: boolean;
}

interface ErrorLayoutProps {
  title: string;
  description: string;
  primaryAction?: ErrorLayoutAction;
  secondaryAction?: ErrorLayoutAction;
  children?: ReactNode;
}

const actionClassNames = (variant: ErrorLayoutAction["variant"]) =>
  ["rb-button", variant === "secondary" ? "rb-button--secondary" : null]
    .filter(Boolean)
    .join(" ");

export const ErrorLayout = ({
  title,
  description,
  primaryAction,
  secondaryAction,
  children,
}: ErrorLayoutProps) => {
  const renderAction = (action: ErrorLayoutAction, fallbackVariant: "primary" | "secondary") => {
    const variant = action.variant ?? fallbackVariant;

    if (action.href) {
      return (
        <a className={actionClassNames(variant)} href={action.href} data-testid={`${variant}-action`}>
          {action.label}
        </a>
      );
    }

    return (
      <Button
        type="button"
        variant={variant}
        onClick={action.onClick}
        disabled={action.disabled}
        data-testid={`${variant}-action`}
      >
        {action.label}
      </Button>
    );
  };

  return (
    <div
      className="min-h-screen flex flex-col items-center justify-center bg-bg-muted text-center p-6 gap-4"
      data-testid="error-layout"
    >
      <div className="max-w-2xl space-y-4">
        <header className="space-y-2">
          <p className="text-sm font-semibold uppercase tracking-wide text-primary">Atlas Homestays</p>
          <h1 className="text-3xl font-bold text-text-primary sm:text-4xl">{title}</h1>
          <p className="text-text-muted text-base sm:text-lg">{description}</p>
        </header>
        {children}
        <div className="flex gap-3 flex-wrap justify-center">
          {primaryAction ? renderAction(primaryAction, "primary") : null}
          {secondaryAction ? renderAction(secondaryAction, "secondary") : null}
        </div>
      </div>
    </div>
  );
};

export default ErrorLayout;

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { addDays, format, startOfMonth } from 'date-fns';
import { Link, useLocation, useNavigate } from 'react-router-dom';
