        // Fetch prior modification requests (best-effort, non-blocking)
        fetch(buildApiUrl(`/api/public/bookings/${bookingId}/modification-requests?t=${encodeURIComponent(token)}`), {
          headers: { Accept: "application/json", ...getApiHeaders() },
