        {/* Stay dates */}
        <div className="rounded-2xl border border-border-subtle bg-bg-surface shadow-level1 p-5 space-y-0 divide-y divide-border-subtle">
          <div className="pb-4 flex items-start gap-3">
            <span className="text-2xl">🏠</span>
            <div>
