const createStaticMapUrl = (apiKey?: string) =>
  apiKey
    ? `https://maps.googleapis.com/maps/api/staticmap?center=${MAP_LOCATION.lat},${MAP_LOCATION.lng}&zoom=15&size=800x420&scale=2&markers=color:red%7C${MAP_LOCATION.lat},${MAP_LOCATION.lng}&key=${apiKey}`
    : FALLBACK_STATIC_MAP_URL;

type MapStatus = "loading" | "ready" | "failed";

const LocationPage = () => {
  const [mapStatus, setMapStatus] = useState<MapStatus>("loading");
  const [, setErrorDetails] = useState<string | null>(null);
  const [, setMapHealth] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const mapContainerRef = useRef<HTMLDivElement | null>(null);
  const hasInitializedMap = useRef(false);
  const apiKey = GOOGLE_MAPS_API_KEY;
  const staticMapUrl = useMemo(() => createStaticMapUrl(apiKey), [apiKey]);

  const logMapFailure = (message: string, detail?: unknown) => {
    // Surface detailed failure information for monitoring.
    console.error(`[LocationPage] ${message}`, detail);
  };

  const initializeMap = () => {
    if (hasInitializedMap.current) return;

    const mapContainer = mapContainerRef.current;

    if (!window.google?.maps?.Map || !window.google.maps.Marker) {
      throw new Error("Google Maps library unavailable after script load");
    }

    if (!mapContainer) {
      throw new Error("Map container missing during initialization");
    }

    // Clear any previous map nodes before re-initializing.
    mapContainer.innerHTML = "";

    const map = new window.google.maps.Map(mapContainer, {
      center: MAP_LOCATION,
      zoom: 15,
      mapTypeControl: false,
      streetViewControl: false,
      fullscreenControl: false,
    });

    new window.google.maps.Marker({
      position: MAP_LOCATION,
      map,
      title: "Atlas Homestays",
    });

    hasInitializedMap.current = true;
    setMapStatus("ready");
    setMapHealth(null);
  };

  useEffect(() => {
    setMapStatus("loading");
    setErrorDetails(null);
    setMapHealth(null);
    hasInitializedMap.current = false;

    if (!apiKey) {
      const message = "Google Maps API key is missing";
      logMapFailure(message);
      setErrorDetails(null); // Don't expose technical details to users
      setMapHealth("missing-api-key");
      setMapStatus("failed");
      return;
    }

    if (window.google?.maps) {
      try {
        initializeMap();
      } catch (initializationError) {
        logMapFailure("Failed to initialize Google Maps with an existing library", initializationError);
        setErrorDetails("We could not load the interactive map just yet.");
        setMapStatus("failed");
        setMapHealth("initialization-failed");
      }
      return;
    }

    const existingScript = document.getElementById(MAP_SCRIPT_ID);
    if (existingScript) {
      existingScript.remove();
    }

    const script = document.createElement("script");
    script.id = MAP_SCRIPT_ID;
    script.async = true;
    script.defer = true;
    script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}`;

    const handleLoad = () => {
      try {
        initializeMap();
      } catch (initializationError) {
        logMapFailure("Google Maps library loaded but initialization failed", initializationError);
        setErrorDetails("We could not load the interactive map just yet.");
        setMapStatus("failed");
        setMapHealth("initialization-failed");
      }
    };

    const handleError = (event: ErrorEvent | Event) => {
      if (import.meta.env.DEV) console.log("[LocationPage] Map script failed, switching to static preview");
      logMapFailure("Failed to load Google Maps script", event);
      setErrorDetails("Google Maps could not be reached right now.");
      setMapStatus("failed");
      setMapHealth("script-failed");
    };

    script.addEventListener("load", handleLoad);
    script.addEventListener("error", handleError);
    document.head.appendChild(script);

    return () => {
      script.removeEventListener("load", handleLoad);
      script.removeEventListener("error", handleError);
    };
  }, [apiKey, retryCount]);

  return (
    <div className="px-4 md:px-10 lg:px-20 py-16 bg-bg-muted">
      <SEO
        title="Location & Neighborhood | Atlas Homestays"
        description="Discover the Kukatpally neighborhood, access routes, and nearby essentials for Atlas Homestays."
      />

      <div className="max-w-6xl mx-auto space-y-12">
        <header className="space-y-3 text-center">
          <Typography variant="subtitle" className="uppercase tracking-[0.2em] text-primary font-semibold">
            Atlas Homestays
          </Typography>
          <Typography as="h1" variant="h1" className="text-text-primary">
            Location & Neighborhood
          </Typography>
          <Typography className="text-text-muted text-lg">
            Find transport options, nearby dining, shopping, and corporate hubs close to Atlas Homestays so you can plan your
            arrival and daily commute with ease.
          </Typography>
        </header>

        <Card className="p-0 overflow-hidden shadow-level2">
          <div className="relative bg-bg-surface border border-border-subtle rounded-2xl overflow-hidden">
            <div className="relative h-[280px] md:h-[420px]">
              {/* Map health indicator removed - no need to show technical status to guests */}

              <div
                aria-busy={mapStatus === "loading"}
                aria-live="polite"
                className={`absolute inset-0 ${mapStatus === "failed" ? "pointer-events-none opacity-0" : "opacity-100"}`}
                ref={mapContainerRef}
              />

              {mapStatus === "loading" && (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-[color:color-mix(in_srgb,var(--bg-surface)_90%,transparent)]">
                  <div className="h-24 w-24 rounded-full bg-[color:color-mix(in_srgb,var(--border-subtle)_70%,transparent)] animate-pulse" aria-hidden />
                  <div className="space-y-2 text-center px-6">
                    <Typography as="p" className="text-text-primary font-semibold">
                      Loading map
                    </Typography>
                    <Typography className="text-text-muted">
                      Fetching directions and landmarks around Atlas Homestays.
                    </Typography>
                  </div>
                </div>
              )}

              {mapStatus === "failed" && (
                <div className="absolute inset-0 flex flex-col gap-4 items-center justify-center bg-bg-surface text-center p-6">
                  {staticMapUrl ? (
                    <OptimizedImage
                      alt="Static map preview of Atlas Homestays"
                      className="h-[180px] w-full object-cover md:h-[240px]"
                      src={staticMapUrl}
                      wrapperClassName="w-full max-w-2xl rounded-xl overflow-hidden border border-border-subtle"
                      onError={(event) => {
                        event.currentTarget.style.display = "none";
                        logMapFailure("Static map preview failed to load", event);
                      }}
                    />
                  ) : null}

                  <div className="space-y-2 max-w-xl">
                    <Typography as="p" className="text-text-primary font-semibold">
                      View on Google Maps
                    </Typography>
                    <Typography className="text-text-muted">
                      Click below to open our location in Google Maps for directions and nearby landmarks.
                    </Typography>
                  </div>

                  <div className="flex flex-col sm:flex-row gap-3 items-center">
                    <Button onClick={() => setRetryCount((count) => count + 1)}>Retry loading map</Button>
                    <a
                      className="rb-button rb-button--secondary"
                      href={`https://maps.google.com/?q=${MAP_LOCATION.lat},${MAP_LOCATION.lng}`}
                      rel="noopener noreferrer"
                      target="_blank"
                    >
                      Open in Google Maps
                    </a>
                  </div>
                </div>
              )}
            </div>
          </div>
        </Card>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <Card className="space-y-3 h-full">
            <Typography as="h2" variant="h2" className="text-text-primary">
              Transport options
            </Typography>
            <div className="space-y-3">
              {transportOptions.map((option) => (
                <div key={option.title} className="space-y-1">
                  <Typography as="h3" variant="h3" className="text-text-primary">
                    {option.title}
                  </Typography>
                  <Typography className="text-text-muted">{option.details}</Typography>
                </div>
              ))}
            </div>
          </Card>

          <Card className="space-y-3 h-full">
            <Typography as="h2" variant="h2" className="text-text-primary">
              Nearby amenities
            </Typography>
            <div className="space-y-3">
              {nearbyAmenities.map((amenity) => (
                <div key={amenity.title} className="space-y-1">
                  <Typography as="h3" variant="h3" className="text-text-primary">
                    {amenity.title}
                  </Typography>
                  <Typography className="text-text-muted">{amenity.details}</Typography>
                </div>
              ))}
            </div>
          </Card>
        </div>

        <Card className="space-y-3">
          <Typography as="h2" variant="h2" className="text-text-primary">
            Landmarks & proximity
          </Typography>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {landmarks.map((landmark) => (
              <div key={landmark.title} className="space-y-1">
                <Typography as="h3" variant="h3" className="text-text-primary">
                  {landmark.title}
                </Typography>
                <Typography className="text-text-muted">{landmark.details}</Typography>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

export default LocationPage;

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { FaHeart, FaRegHeart } from 'react-icons/fa';
import { buildApiUrl } from '@/api/client';
import { formatCurrency } from '@/utils/formatting'; // TASK-1872
import { getFavoriteIds, toggleFavorite } from '@/utils/guestHistory'; // TASK-1873
import OptimizedImage from '@/components/ui/OptimizedImage'; // TASK-1874
import SkeletonCard from '@/components/apartments/SkeletonCard'; // TASK-1875
import SEO from '@/components/SEO'; // TASK-1876

type MarketplaceItem = {
  id: number;
  tenantSlug: string;
  tenantName: string;
  tenantCategory?: string;
  title: string;
  city?: string;
  pricePerNight: number;
  maxGuests: number;
  coverImageUrl?: string;
  slug: string;
  // TASK-1873: rating + reviewCount for parity with ListingCard
  rating?: number | null;
  reviewCount?: number | null;
};

type ApiResponse = { items: MarketplaceItem[]; total: number; page: number; pageSize: number };

export default function MarketplaceHomepage() {
  const [category, setCategory] = useState<'all' | 'homes' | 'rooms'>('all');
  const [query, setQuery] = useState('');
  const [items, setItems] = useState<MarketplaceItem[]>([]);
  const [loading, setLoading] = useState(true);
  // TASK-1873: save-heart state keyed by listing id
  const [favEpoch, setFavEpoch] = useState(0);
  const favIds = useMemo(() => new Set(getFavoriteIds()), [favEpoch]);

  const apiPath = useMemo(() => {
    const p = new URLSearchParams();
    if (category !== 'all') p.set('category', category);
    if (query.trim()) p.set('city', query.trim());
    p.set('page', '1');
    p.set('pageSize', '20');
    return `/marketplace/listings?${p.toString()}`;
  }, [category, query]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    fetch(buildApiUrl(apiPath))
      .then(async (r) => (r.ok ? ((await r.json()) as ApiResponse) : { items: [] as MarketplaceItem[] }))
      .then((data) => {
        if (!cancelled) setItems(data.items ?? []);
      })
      .catch(() => {
        if (!cancelled) setItems([]);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [apiPath]);

  return (
    <section className="mx-auto w-full max-w-6xl px-4 py-8" data-testid="marketplace-homepage">
      {/* TASK-1876: SEO meta for marketplace homepage */}
      <SEO
        title="Atlas Stays Marketplace — Verified homes & rooms across India"
        description="Discover homes and rooms across verified hosts on Atlas Stays. Direct booking, no platform fee."
      />
      <h1 className="text-3xl font-bold text-text-primary">Atlas Stays Marketplace</h1>
      <p className="mt-2 text-text-body">Discover homes and rooms across verified hosts.</p>

      <div className="mt-6 flex flex-wrap items-center gap-3">
        <input
          data-testid="marketplace-search"
          className="min-h-[44px] rounded-xl border border-border px-4 py-2"
          placeholder="Search by city"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        {(['all', 'homes', 'rooms'] as const).map((c) => (
          <button
            key={c}
            data-testid={`marketplace-filter-${c}`}
            className={`min-h-[44px] rounded-xl px-4 py-2 ${category === c ? 'bg-black text-white' : 'bg-gray-100 text-black'}`}
            onClick={() => setCategory(c)}
          >
            {c[0].toUpperCase() + c.slice(1)}
          </button>
        ))}
      </div>

      <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3" data-testid="marketplace-grid">
        {/* TASK-1875: skeleton cards while loading */}
        {loading && Array.from({ length: 6 }).map((_, i) => <SkeletonCard key={i} />)}

        {!loading &&
          items.map((item) => {
            // TASK-1869/1873: GST — 5% for ≤₹7,500/night, 18% above (Sept 2025 reform)
            const gstRate = item.pricePerNight > 7500 ? 1.18 : 1.05;
            const gstPct = item.pricePerNight > 7500 ? 18 : 5;
            const estTotal = Math.round(item.pricePerNight * 2 * gstRate);
            const isFav = favIds.has(item.id);

            return (
              <article
                key={item.id}
                className="relative flex flex-col overflow-hidden rounded-2xl border border-border bg-bg-surface shadow-sm transition-colors hover:border-border-subtle"
                data-testid="marketplace-card"
              >
                {/* TASK-1874: OptimizedImage replaces raw <img> */}
                <div className="h-40 w-full bg-gradient-to-br from-bg-muted to-bg-surface">
                  <OptimizedImage
                    src={item.coverImageUrl ?? ''}
                    alt={item.title || 'Listing photo'}
                    className="h-full w-full object-cover"
                    wrapperClassName="h-full"
                    sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                  />
                </div>

                {/* TASK-1873: save heart */}
                <button
                  type="button"
                  aria-label={isFav ? 'Remove from saved' : 'Save listing'}
                  className="absolute right-2 top-2 z-10 rounded-full bg-bg-surface/95 p-2 shadow border border-border-subtle hover:opacity-90 transition-opacity"
                  onClick={() => {
                    toggleFavorite(item.id);
                    setFavEpoch((e) => e + 1);
                  }}
                >
                  {isFav
                    ? <FaHeart className="h-4 w-4 text-red-500" aria-hidden />
                    : <FaRegHeart className="h-4 w-4 text-text-muted" aria-hidden />}
                </button>

                <div className="flex flex-1 flex-col gap-2 p-4">
                  <div className="text-xs uppercase tracking-wide text-text-muted">{item.tenantName}</div>
                  <h2 className="text-base font-semibold text-text-primary leading-snug">{item.title}</h2>

                  {/* TASK-1873: neighborhood/city chip */}
                  {item.city && (
                    <span className="w-fit rounded-full bg-bg-muted px-2.5 py-0.5 text-xs font-medium text-text-secondary">
                      {item.city}
                    </span>
                  )}

                  <p className="text-sm text-text-body">Sleeps up to {item.maxGuests} guests</p>

                  {/* TASK-1873: rating row */}
                  {item.rating != null && item.rating > 0 && (
                    <p className="text-sm font-medium text-accent-primary">
                      {'★'.repeat(Math.round(item.rating))}
                      <span className="ml-1 text-text-muted">{item.rating.toFixed(1)}</span>
                      {item.reviewCount != null && item.reviewCount > 0 && (
                        <span className="ml-1 text-text-muted">({item.reviewCount})</span>
                      )}
                    </p>
                  )}

                  {/* TASK-1872: formatCurrency replaces raw 'INR X' */}
                  <p className="text-xl font-bold text-text-primary">
                    {formatCurrency(item.pricePerNight, { maximumFractionDigits: 0 })}
                    <span className="ml-1 text-sm font-normal text-text-muted">/ night</span>
                  </p>

                  {/* TASK-1873: GST-inclusive estimate */}
                  <p className="text-xs text-text-muted">
                    Est. total: {formatCurrency(estTotal, { maximumFractionDigits: 0 })} (incl. {gstPct}% GST, 2 nights)
                  </p>

                  <Link
                    className="mt-auto inline-flex min-h-[40px] items-center justify-center rounded-xl bg-black px-4 py-2 text-sm font-semibold text-white hover:bg-gray-800 transition-colors"
                    to={`/${item.slug}`}
                  >
                    View home
                  </Link>
                </div>
              </article>
            );
          })}
      </div>
    </section>
  );
}

import { useEffect, useState } from "react";
import { useSearchParams, Link } from "react-router-dom";
import SEO from "../components/SEO";
import { buildApiUrl, getApiHeaders } from "../api/client";
import { messageFromApiResponse } from "../utils/serverErrorFromResponse";
import { getContactEmail } from "../config/contact";

interface BookingItem {
  id: number;
  bookingRef: string;
  propertyName: string;
  listingName: string;
  checkinDate: string;
  checkoutDate: string;
  status: string;
  totalAmount: number;
  token: string;
}

const STATUS_COLORS: Record<string, string> = {
  Confirmed: "bg-green-100 text-green-800",
  CheckedIn: "bg-blue-100 text-blue-800",
  CheckedOut: "bg-gray-100 text-gray-700",
  Cancelled: "bg-red-100 text-red-700",
  Lead: "bg-yellow-100 text-yellow-800",
};

export default function MyBookingsPage() {
  const [searchParams] = useSearchParams();
  const guestId = searchParams.get("guestId");
  const token = searchParams.get("t");

  const [bookings, setBookings] = useState<BookingItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!guestId || !token) {
      setError("Booking history link is missing guest details. Please use the link from your booking confirmation.");
      setLoading(false);
      return;
    }
    const url = buildApiUrl(
      `/api/guest/bookings?guestId=${encodeURIComponent(guestId)}&t=${encodeURIComponent(token)}`
    );
    fetch(url, { headers: { Accept: "application/json", ...getApiHeaders() } })
      .then(async (res) => {
        if (res.status === 404) throw new Error("No bookings found. Please use the link from your booking confirmation.");
        if (!res.ok) throw new Error(await messageFromApiResponse(res));
        return res.json() as Promise<BookingItem[]>;
      })
      .then((data) => setBookings(Array.isArray(data) ? data : []))
      .catch((err: Error) => setError(err.message))
      .finally(() => setLoading(false));
  }, [guestId, token]);

  if (loading) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center">
        <div className="flex flex-col items-center gap-3">
          <div className="w-8 h-8 border-3 border-border-subtle border-t-brand-primary rounded-full animate-spin" />
          <p className="text-sm text-text-secondary">Loading&hellip;</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <div className="max-w-md text-center space-y-4">
          <div className="text-4xl">📋</div>
          <h1 className="text-xl font-bold text-text-primary">Bookings not found</h1>
          <p className="text-sm text-text-secondary">{error}</p>
          <button
            type="button"
            onClick={() => window.location.reload()}
            className="inline-flex items-center justify-center rounded-lg bg-brand-primary text-white text-base font-medium px-4 py-3 hover:opacity-95 transition-opacity"
            data-testid="my-bookings-retry"
          >
            Try again
          </button>
          <div className="flex flex-col sm:flex-row gap-3 justify-center items-stretch">
            <a
              href={`mailto:${getContactEmail()}?subject=${encodeURIComponent("Atlas booking history link")}`}
              className="inline-flex items-center justify-center rounded-lg border border-border-subtle bg-bg-surface text-text-primary text-base font-medium px-4 py-3 hover:bg-bg-muted transition-colors"
            >
              Email support
            </a>
            <Link to="/" className="inline-flex items-center justify-center text-base text-brand-primary underline underline-offset-2 px-2 py-3">
              Return to homepage
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <SEO title="My Bookings" description="View your booking history at Atlas Homestays." />
      <div className="max-w-2xl mx-auto px-4 sm:px-6 py-10 space-y-6">
        <div className="space-y-1">
          <h1 className="text-2xl font-bold text-text-primary">My Bookings</h1>
          <p className="text-sm text-text-secondary">{bookings.length} booking{bookings.length !== 1 ? "s" : ""} found</p>
        </div>

        {bookings.length === 0 ? (
          <div className="text-center py-12 space-y-4">
            <p className="text-text-secondary text-sm">No bookings found.</p>
            <Link to="/" className="btn-chip inline-block">
              Browse our homes
            </Link>
            <p className="text-text-secondary text-xs max-w-md mx-auto">
              Bookings are linked to the email or phone used during checkout. If you booked with a different contact, open the confirmation link from that email or WhatsApp message instead.
            </p>
            <p className="text-text-secondary text-xs max-w-md mx-auto">
              Need help? Call us at{" "}
              <a href="tel:+917032493290" className="underline underline-offset-2 text-brand-primary">+91 7032 493 290</a>{" "}
              to locate a booking by reference number.
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {bookings.map((b) => {
              const statusClass = STATUS_COLORS[b.status] ?? "bg-gray-100 text-gray-700";
              return (
                <Link
                  key={b.id}
                  to={`/booking/${b.id}?t=${encodeURIComponent(b.token)}`}
                  className="block rounded-xl border border-border-subtle bg-bg-surface px-4 py-4 hover:border-brand-primary/40 transition-colors"
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="space-y-0.5">
                      <p className="text-base font-semibold text-text-primary">{b.listingName}</p>
                      <p className="text-sm text-text-muted">{b.propertyName}</p>
                    </div>
                    <span className={`text-xs font-medium px-2 py-0.5 rounded-full shrink-0 ${statusClass}`}>
                      {b.status}
                    </span>
                  </div>
                  <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-sm text-text-secondary">
                    <span>{b.checkinDate} → {b.checkoutDate}</span>
                    <span className="font-mono text-text-muted">#{b.bookingRef}</span>
                    <span className="ml-auto font-medium text-text-primary">₹{Number(b.totalAmount).toLocaleString("en-IN")}</span>
                  </div>
                </Link>
