import { getTenantContext } from '../tenant/tenantContext';
import { propertyData } from '../data';
import { getTenantOverrides, getTenantPublicListingIdAllowlist } from '../tenant/tenantOverrides';

/**
 * @deprecated Use useTenantListings() hook instead to fetch properties from the API.
 * This function uses hardcoded property data and is kept only for backward compatibility.
 * New code should use the API-based useTenantListings() hook which fetches fresh data.
 */
export function getTenantPropertyData() {
  const tenant = getTenantContext();
  const tenantName = tenant?.name ?? 'Atlas Homestays';
  const overrides = getTenantOverrides(tenant?.slug);

  let filtered = propertyData;

  const allowlist = getTenantPublicListingIdAllowlist(overrides);
  if (allowlist.size > 0) {
    filtered = propertyData.filter((property) => {
      const listingId = Number(property.listingId ?? property.id);
      return Number.isFinite(listingId) && allowlist.has(listingId);
    });
  }

  if (!tenant?.name) {
    return filtered;
  }

  return filtered.map(property => ({
    ...property,
    property_name: property.property_name.replace(/^Atlas (Homes|Penthouse)/, tenantName),
    property_description: property.property_description.replace(/Atlas (Homes|Penthouse)/g, tenantName),
  }));
}

/** TASK-1469: Map Razorpay `payment.failed` codes to short guest-facing copy. */
// Hardening for BUG-ONBOARD-1 (incident 2026-05-02). See atlas-e2e/docs/incidents/2026-05-02-property-registration-failure.md

const MAP: Record<string, string> = {
  BAD_REQUEST_ERROR: 'Your bank or UPI app declined this attempt. Try another card or UPI ID.',
  GATEWAY_ERROR: 'The payment gateway had a problem. Please try again in a few minutes.',
  NETWORK_ERROR: 'We could not reach the payment network. Check your connection and try again.',
  SERVER_ERROR: 'The payment service returned an error. Try again shortly or contact support@atlashomestays.com.',
  USER_CANCELLED: 'Payment was cancelled before completion.',
};

export function mapRazorpayFailureCode(code: string | undefined, fallbackDescription?: string): string {
  const c = (code ?? '').trim().toUpperCase();
  if (c && MAP[c]) return MAP[c];
  const d = (fallbackDescription ?? '').trim();
  if (d) return d;
  return 'Payment could not be completed. You can try again or pick a different payment method.';
}

